function addDays(dateStr,days){const d=new Date(`${dateStr}T12:00:00`);d.setDate(d.getDate()+days);return localDateString(d)}
function addMonths(dateStr,months){const d=new Date(`${dateStr}T12:00:00`);d.setMonth(d.getMonth()+months);return localDateString(d)}
function formatDate(s){if(!s)return'';const d=new Date(`${s}T12:00:00`);return `${d.getDate()} ${MONTHS[d.getMonth()]}`}
function formatRange(a,b){if(a&&b)return `${formatDate(a)} — ${formatDate(b)}`;return formatDate(a||b)}
