function normalizeEntity(e,type){
  const n={...e};n.id ||= uid(type);n.deleted=!!n.deleted;n.archived=!!n.archived;n.updatedAt ||= nowIso();n.updatedBy ||= getDeviceId();n.fieldClock ||= {};
  Object.keys(n).forEach(k=>{if(!['id','updatedAt','updatedBy','fieldClock'].includes(k)&&!n.fieldClock[k])n.fieldClock[k]=n.updatedAt});
  if(type==='task'){
    n.tags=Array.isArray(n.tags)?n.tags:[];n.subtasks=Array.isArray(n.subtasks)?n.subtasks:[];n.recurrence ||= 'none';n.reminder ??='none';n.position=Number.isFinite(n.position)?n.position:100;n.calendarEventId ||= null;n.calendarSyncedAt ||= null;
  }
  if(type==='sprint')n.completed=!!n.completed;
  return n;
}
function normalizeState(input){
  const b=input&&typeof input==='object'?clone(input):defaultState();
  b.schemaVersion=2;b.meta ||= {updatedAt:nowIso(),updatedBy:getDeviceId(),lastSyncAt:null,conflicts:[]};b.meta.conflicts=Array.isArray(b.meta.conflicts)?b.meta.conflicts:[];
  b.projects=(Array.isArray(b.projects)?b.projects:[]).map(x=>normalizeEntity(x,'project'));
  b.sprints=(Array.isArray(b.sprints)?b.sprints:[]).map(x=>normalizeEntity(x,'sprint'));
  b.tasks=(Array.isArray(b.tasks)?b.tasks:[]).map(x=>normalizeEntity(x,'task'));
  b.statuses=Array.isArray(b.statuses)&&b.statuses.length?b.statuses:clone(DEFAULT_STATUSES);
  b.settings ||= {};b.settings={id:'settings',theme:'lavender',accent:'#8f75b7',customTheme:null,autoSync:true,syncInterval:180,calendarMode:'month',defaultSprintDuration:'2w',onboardingDismissed:false,githubOwner:'',githubRepo:'anya-task-manager',pagesUrl:'',updatedAt:nowIso(),updatedBy:getDeviceId(),fieldClock:{},...b.settings};
  b.settings.fieldClock ||= {};Object.keys(b.settings).forEach(k=>{if(!['id','updatedAt','updatedBy','fieldClock'].includes(k)&&!b.settings.fieldClock[k])b.settings.fieldClock[k]=b.settings.updatedAt});
  return b;
}
async function loadState(){
  let raw=await dbGet(STATE_KEY);
  if(!raw){
    try{const legacy=localStorage.getItem(LEGACY_KEY);if(legacy){raw=JSON.parse(legacy);localStorage.removeItem(LEGACY_KEY)}}catch{}
  }
  state=normalizeState(raw||defaultState());
  await persist(false);
}
async function persist(render=true){state.meta.updatedAt=nowIso();state.meta.updatedBy=getDeviceId();await dbSet(STATE_KEY,state);syncNeeded=true;if(render)renderAll()}
function touch(entity,fields=[]){const stamp=nowIso();entity.updatedAt=stamp;entity.updatedBy=getDeviceId();entity.fieldClock ||= {};fields.forEach(f=>entity.fieldClock[f]=stamp);return entity}
function setFields(entity,patch){const changed=[];for(const [k,v] of Object.entries(patch)){const before=JSON.stringify(entity[k]);const after=JSON.stringify(v);if(before!==after){entity[k]=v;changed.push(k)}}if(changed.length)touch(entity,changed);return changed.length>0}
function activeProjects(){return state.projects.filter(x=>!x.deleted&&!x.archived)}
function activeSprints(){return state.sprints.filter(x=>!x.deleted&&!x.archived&&!x.completed)}
function activeTasks(){return state.tasks.filter(x=>!x.deleted&&!x.archived)}
function archivedTasks(){return state.tasks.filter(x=>!x.deleted&&x.archived)}
function getProject(id){return state.projects.find(x=>x.id===id&&!x.deleted)}
function getSprint(id){return state.sprints.find(x=>x.id===id&&!x.deleted)}
function getTask(id){return state.tasks.find(x=>x.id===id&&!x.deleted)}
function statusInfo(id){return state.statuses.find(s=>s.id===id)||state.statuses[0]||DEFAULT_STATUSES[0]}
function doneStatusId(){return state.statuses[state.statuses.length-1]?.id||'done'}
function currentSprint(){const today=localDateString();return activeSprints().filter(s=>s.startDate<=today&&s.endDate>=today).sort((a,b)=>a.endDate.localeCompare(b.endDate))[0]||activeSprints().sort((a,b)=>(b.startDate||'').localeCompare(a.startDate||''))[0]||null}
function allTags(){const map=new Map();activeTasks().forEach(t=>t.tags.forEach(tag=>map.set(tag,(map.get(tag)||0)+1)));return [...map].sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0]))}
function taskMatchesFilters(t){if(selectedProjectId&&t.projectId!==selectedProjectId)return false;if(searchTerm){const hay=`${t.title} ${t.description||''} ${(t.tags||[]).join(' ')}`.toLowerCase();if(!hay.includes(searchTerm.toLowerCase()))return false}if(filterTag&&!t.tags.includes(filterTag))return false;if(filterPriority!=='all'&&t.priority!==filterPriority)return false;return true}
function sortTasks(a,b){return (a.position??9999)-(b.position??9999)||(a.date||'9999').localeCompare(b.date||'9999')||(a.time||'99').localeCompare(b.time||'99')||a.title.localeCompare(b.title)}
function nextPosition(list){return list.length?Math.max(...list.map(x=>Number(x.position)||0))+100:100}

