async function init(){
  cacheDom();db=await openDb();await loadState();calendarMode=state.settings.calendarMode||'month';if(new URLSearchParams(location.search).get('setup')==='google')currentView='settings';applyTheme();bindNavigation();bindModals();buildColorPresets();bindForms();bindSync();bindGlobal();bindInstallShortcut();restoreSessionToken();selectedSprintId=currentSprint()?.id||null;renderAll();document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('is-active',x.dataset.view===currentView));registerServiceWorker();scheduleNotifications();setupAutoSync();setTimeout(setupGoogleTokenClient,200);if(googleAccessToken&&navigator.onLine)setTimeout(()=>autoSync('startup'),600)
}
function applyTheme(){const t=state.settings.customTheme||THEMES[state.settings.theme]||THEMES.lavender,root=document.documentElement;root.style.setProperty('--accent',state.settings.accent||t.accent);root.style.setProperty('--bg',t.bg||'#f6f3fb');root.style.setProperty('--accent-soft',t.soft||'#eee7f8');root.style.setProperty('--panel',t.panel||'#fcfaff');root.style.setProperty('--panel-2',t.panel2||'#f4eef9');root.style.setProperty('--surface',t.surface||t.bg||'#f8f4fc');root.style.setProperty('--line',t.line||'#e5dcee');document.querySelector('meta[name="theme-color"]')?.setAttribute('content',state.settings.accent||t.accent)}
function bindNavigation(){document.addEventListener('click',ev=>{const btn=ev.target.closest('[data-view]');if(!btn)return;currentView=btn.dataset.view;document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('is-active',x.dataset.view===currentView));renderView()});dom.mobileSettingsBtn.addEventListener('click',()=>{currentView='settings';document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('is-active',false));renderView()})}
